const assets=[{symbol:'BTC',name:'بیت‌کوین',icon:'₿',price:'67,420.80',change:'+2.41%',up:true,watch:true},{symbol:'ETH',name:'اتریوم',icon:'Ξ',price:'3,520.45',change:'+1.82%',up:true,watch:true},{symbol:'SOL',name:'سولانا',icon:'◎',price:'148.32',change:'−0.64%',up:false,watch:false},{symbol:'USDC',name:'یو‌اس‌دی کوین',icon:'$',price:'1.00',change:'+0.01%',up:true,watch:false}];
let filter='all';
function renderMarket(){const rows=assets.filter(a=>filter==='all'||a.watch);document.querySelector('#market-rows').innerHTML=rows.length?rows.map(a=>`<tr><td><span class="coin"><span class="coin-icon" aria-hidden="true">${a.icon}</span><b dir="ltr">${a.symbol}</b><small>${a.name}</small></span></td><td>$${a.price}</td><td class="${a.up?'positive':'negative'}">${a.change}</td><td><svg class="spark" viewBox="0 0 80 24" aria-hidden="true"><path d="${a.symbol==='USDC'?'M0 12L80 12':a.up?'M0 20L9 15L16 17L24 10L32 14L40 8L48 12L56 4L64 7L72 2L80 5':'M0 5L9 8L16 4L24 11L32 8L40 15L48 10L56 17L64 14L72 22L80 19'}" fill="none" stroke="${a.up?'#c6ff52':'#fa7d78'}" stroke-width="1.5"/></svg></td><td><button class="star ${a.watch?'chosen':''}" data-symbol="${a.symbol}" aria-label="${a.watch?'حذف':'افزودن'} ${a.name} ${a.watch?'از':'به'} منتخب‌ها" aria-pressed="${a.watch}">${a.watch?'★':'☆'}</button></td></tr>`).join(''):'<tr><td colspan="5" class="empty">هنوز دارایی منتخبی نداری. از بخش «همه» انتخاب کن.</td></tr>'}
renderMarket();
document.querySelector('#market-rows').addEventListener('click',e=>{const star=e.target.closest('[data-symbol]');if(!star)return;const a=assets.find(a=>a.symbol===star.dataset.symbol);a.watch=!a.watch;renderMarket()});
document.querySelectorAll('[data-filter]').forEach(b=>b.addEventListener('click',()=>{filter=b.dataset.filter;document.querySelectorAll('[data-filter]').forEach(x=>{x.classList.toggle('active',x===b);x.setAttribute('aria-pressed',String(x===b))});renderMarket()}));
const month='M0 151L25 143L50 150L75 125L100 132L125 115L150 122L175 101L200 108L225 82L250 97L275 76L300 82L325 55L350 69L375 48L400 58L425 34L450 43L475 30L500 39L525 20L550 28L580 12L620 19';const week='M0 130L25 139L50 125L75 132L100 108L125 117L150 97L175 104L200 84L225 96L250 83L275 102L300 76L325 85L350 61L375 77L400 67L425 42L450 56L475 51L500 60L525 43L550 50L580 32L620 42';
document.querySelectorAll('[data-range]').forEach(b=>b.addEventListener('click',()=>{const weekly=b.dataset.range==='week';document.querySelectorAll('[data-range]').forEach(x=>{x.classList.toggle('active',x===b);x.setAttribute('aria-pressed',String(x===b))});const d=weekly?week:month;document.querySelector('#line-path').setAttribute('d',d);document.querySelector('#area-path').setAttribute('d',d+'V180H0Z');document.querySelector('#delta').textContent=weekly?'↗ +2.18%':'↗ +8.42%';document.querySelector('.x-labels').innerHTML=(weekly?['۲۴ مهر','۲۵ مهر','۲۷ مهر','۲۹ مهر','۳۰ مهر']:['۱ مهر','۷ مهر','۱۴ مهر','۲۱ مهر','۳۰ مهر']).map(x=>`<span>${x}</span>`).join('')}));
const heights=[18,30,22,39,27,33,19,36,47,31,43,25,46,37,56,40,33,52,36,50,30,42,55,38,49,32,44,36];document.querySelector('.candles').innerHTML=heights.map((h,i)=>`<i class="candle ${i%4===2?'down':''}" style="height:${h}px;transform:translateY(${45-i*3}px)"></i>`).join('');document.querySelector('.volume-bars').innerHTML=[6,10,7,15,12,18,13,20,14,17,11,19].map(h=>`<i style="height:${h}px"></i>`).join('');
const menu=document.querySelector('.menu');menu.addEventListener('click',()=>{const open=document.querySelector('.navlinks').classList.toggle('open');menu.setAttribute('aria-expanded',String(open));menu.setAttribute('aria-label',open?'بستن منو':'باز کردن منو')});document.querySelectorAll('.navlinks a').forEach(a=>a.addEventListener('click',()=>{document.querySelector('.navlinks').classList.remove('open');menu.setAttribute('aria-expanded','false');menu.setAttribute('aria-label','باز کردن منو')}));document.addEventListener('keydown',e=>{if(e.key==='Escape'){document.querySelector('.navlinks').classList.remove('open');menu.setAttribute('aria-expanded','false')}});
